(function(){
  'use strict';
  const MASTER='8283ab91b10f89ac758d09ecf5fb4d6343536600a06dd468b1cc1ecf4ec747c4';
  const doc=window.ATLAS_CLARUS_DATA||{};
  const colors=doc.colors||[];
  let selected=colors.find(c=>c.id===4665)||colors[0];
  let filtered=colors.slice(); let page=0; const perPage=96;
  const $=s=>document.querySelector(s);
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const views=[...document.querySelectorAll('.view')];
  function route(){const id=(location.hash||'#home').slice(1);views.forEach(v=>v.classList.toggle('active',v.id===id));if(id==='wheel')drawWheel();if(id==='appearance')drawSimulation();scrollTo(0,0)}
  addEventListener('hashchange',route);
  function luminance(rgb){return .2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2]}
  function selectedHtml(c){return `<div class="selected-swatch" style="background:${esc(c.hex)}"></div><p class="eyebrow">FROZEN REFERENCE IDENTITY</p><h2>${esc(c.ref)}</h2><dl><dt>atlas_row_id</dt><dd>${c.id}</dd><dt>Human row</dt><dd>${c.id+1}</dd><dt>RGB</dt><dd>${c.rgb.join(' / ')}</dd><dt>HEX</dt><dd>${esc(c.hex)}</dd><dt>CIELAB</dt><dd>${c.lab.map(n=>Number(n).toFixed(2)).join(' / ')}</dd><dt>Master</dt><dd>verified metadata</dd></dl><div class="selection-actions"><button data-open-wheel>Open in Wheel</button><button data-copy>Copy identity</button></div>`}
  function select(c){selected=c;$('#selection').innerHTML=selectedHtml(c);$('#wheel-selection').innerHTML=selectedHtml(c);document.querySelectorAll('[data-open-wheel]').forEach(b=>b.onclick=()=>{location.hash='wheel'});document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>copy(`${c.ref} | ${c.hex} | atlas_row_id ${c.id} | master_sha256 ${MASTER}`));drawSimulation()}
  async function copy(s){try{await navigator.clipboard.writeText(s)}catch(_){const t=document.createElement('textarea');t.value=s;document.body.append(t);t.select();document.execCommand('copy');t.remove()}}
  function render(){const start=page*perPage;const rows=filtered.slice(start,start+perPage);$('#colour-grid').innerHTML='';rows.forEach(c=>{const b=document.createElement('button');b.className='colour-card'+(luminance(c.rgb)>165?' dark-text':'');b.style.setProperty('--swatch',c.hex);b.innerHTML=`<b>${esc(c.ref)}</b><small>${esc(c.hex)} · ID ${c.id}</small>`;b.onclick=()=>select(c);$('#colour-grid').append(b)});const pages=Math.max(1,Math.ceil(filtered.length/perPage));$('#library-status').textContent=`${filtered.length.toLocaleString('en')} of ${colors.length.toLocaleString('en')} master references · PKL Full Reference`;$('#page-info').textContent=`Page ${page+1} / ${pages}`;$('#prev-page').disabled=page===0;$('#next-page').disabled=page>=pages-1}
  function filter(){const q=$('#search').value.trim().toUpperCase();const l=$('#lightness').value;filtered=colors.filter(c=>(l==='all'||Math.round(c.lab[0])===Number(l))&&(!q||c.ref.includes(q)||c.hex.toUpperCase().includes(q)||String(c.id)===q));page=0;render()}
  for(let l=5;l<=95;l+=5){const o=document.createElement('option');o.value=l;o.textContent=`L* ${String(l).padStart(3,'0')}`;$('#lightness').append(o)}
  $('#search').oninput=filter;$('#lightness').onchange=filter;$('#clear-search').onclick=()=>{$('#search').value='';$('#lightness').value='all';filter()};$('#prev-page').onclick=()=>{page--;render()};$('#next-page').onclick=()=>{page++;render()};
  function hcl(c){const m=c.ref.match(/H(\d+)_L(\d+)_C(\d+)/);return m?m.slice(1).map(Number):[0,c.lab[0],0]}
  function drawWheel(){const cv=$('#wheel-canvas');if(!cv)return;const ctx=cv.getContext('2d');const w=cv.width,h=cv.height,cx=w/2,cy=h/2,R=w*.43;ctx.clearRect(0,0,w,h);const grad=ctx.createRadialGradient(cx,cy,25,cx,cy,R);grad.addColorStop(0,'#e8e5df');grad.addColorStop(.45,'#75777b');grad.addColorStop(1,'#171c23');ctx.fillStyle=grad;ctx.beginPath();ctx.arc(cx,cy,R,0,Math.PI*2);ctx.fill();const [sh,sl,sc]=hcl(selected);const layer=colors.filter(c=>Math.abs(hcl(c)[1]-sl)<2.6);layer.forEach(c=>{const [H,,C]=hcl(c);const a=(H-90)*Math.PI/180;const r=Math.min(R,C/105*R);ctx.fillStyle=c.hex;ctx.beginPath();ctx.arc(cx+Math.cos(a)*r,cy+Math.sin(a)*r,3.2,0,Math.PI*2);ctx.fill()});const a=(sh-90)*Math.PI/180,r=Math.min(R,sc/105*R);ctx.strokeStyle='#fff';ctx.lineWidth=4;ctx.beginPath();ctx.arc(cx+Math.cos(a)*r,cy+Math.sin(a)*r,10,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#fff';ctx.font='18px system-ui';ctx.textAlign='center';ctx.fillText(`L* ${sl}`,cx,cy+6)}
  const mats={paper:[.98,.97,.94],polymer:[1.02,1.02,1.03],metal:[.78,.82,.86],textile:[.86,.84,.81],glass:[.8,.9,1],wood:[.92,.78,.62]};
  function drawSimulation(){const cv=$('#sim-canvas');if(!cv||!selected)return;const ctx=cv.getContext('2d'),w=cv.width,h=cv.height;const mat=$('#material').value,fin=$('#finish').value,ill=$('#illuminant').value,angle=Number($('#angle').value),depth=Number($('#depth').value)/100;$('#angle-output').value=angle+'°';const light=ill==='A'?[1.16,.88,.62]:ill==='D65'?[.93,.98,1.1]:[1.04,1,.92];const base=selected.rgb.map((v,i)=>v*mats[mat][i]*light[i]);const img=ctx.createImageData(w,h);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const p=(y*w+x)*4,n=Math.sin(x*.14)+Math.cos(y*.17)+Math.sin((x+y)*.037),glint=Math.pow(Math.max(0,1-Math.abs(x/w-(.25+angle/160))),fin==='gloss'?18:fin==='metallic'?7:40)*(fin==='gloss'?90:fin==='metallic'?120:25);for(let i=0;i<3;i++)img.data[p+i]=Math.max(0,Math.min(255,base[i]*(1+n*depth*.075)+glint));img.data[p+3]=255}ctx.putImageData(img,0,0);ctx.fillStyle='#000b';ctx.fillRect(20,h-85,520,62);ctx.fillStyle='#fff';ctx.font='bold 22px system-ui';ctx.fillText(selected.ref,38,h-52);ctx.font='15px system-ui';ctx.fillStyle='#cbd5e1';ctx.fillText(`${mat} · ${fin} · ${ill} · ${angle}° · simulated screen appearance`,38,h-28);$('#sim-caption').textContent=`Frozen source: ${selected.ref} · ${selected.hex}. Appearance layer: simulated. measured_qc_status = NOT_MEASURED.`}
  ['material','finish','illuminant','angle','depth'].forEach(id=>$('#'+id).oninput=drawSimulation);
  const workflows=[
    {name:'Inkscape',version:'v0.3.0',status:'reference handoff',steps:['SVG colour','8-bit sRGB','Full-master match','Freeze row ID','Write + audit'],note:'Demonstrates direct fill/stroke and CSS colour handoff. Runtime validation belongs to the desktop extension package.'},
    {name:'GIMP',version:'v0.1.3',status:'engineering beta',steps:['Image pixel','8-bit sRGB','Full-master match','Freeze identity','Document result'],note:'Demonstrates deterministic pixel-to-reference binding. It is not an image-wide physical proof.'},
    {name:'Krita',version:'v0.3.4',status:'runtime gate',steps:['Document colour','8-bit sRGB','Full-master search','Freeze row ID','Plugin audit'],note:'Demonstrates the creative-application lookup boundary. Installation and runtime verification occur in Krita.'},
    {name:'Scribus',version:'MVP proof',status:'reference + production',steps:['Frozen identity','Feasibility','ICC/device values','PDF/X inspection','Measured QC later'],note:'Separates reference identity from production mapping. No measured print result is claimed.'}
  ];
  function showWorkflow(i){const w=workflows[i];$('#workflow-detail').innerHTML=`<p class="eyebrow">${esc(w.version)} · ${esc(w.status)}</p><h3>ATLAS Clarus × ${esc(w.name)}</h3><div class="steps">${w.steps.map((s,n)=>`<div class="step"><strong>0${n+1}</strong>${esc(s)}</div>`).join('')}</div><p>${esc(w.note)}</p><p class="boundary">PKL Full Reference remains the identity authority. Production or application-specific values cannot redefine the frozen source identity.</p>`}
  workflows.forEach((w,i)=>{const b=document.createElement('button');b.className='workflow-card';b.innerHTML=`<b>${esc(w.name)}</b><span>${esc(w.version)}<br>${esc(w.status)}</span>`;b.onclick=()=>showWorkflow(i);$('#workflow-cards').append(b)});
  if(doc.master_sha256!==MASTER||colors.length!==13283){document.body.innerHTML='<main class="view active"><h1>Bundle validation failed</h1><p>The embedded master metadata or reference count does not match the release baseline.</p></main>';return}
  select(selected);render();showWorkflow(0);route();
})();
